package com.hoteluq.view;
import com.hoteluq.controller.HotelController;import com.hoteluq.model.*;import javafx.application.Application;import javafx.geometry.Insets;import javafx.scene.Scene;import javafx.scene.control.*;import javafx.scene.layout.*;import javafx.stage.Stage;import java.time.LocalDate;
public class HotelView extends Application {private final HotelController controller=new HotelController();public void start(Stage stage){Label title=new Label("HotelUQ | Sistema Integral de Gestión Hotelera");title.setStyle("-fx-font-size: 20px; -fx-font-weight: bold;");ComboBox<String> rooms=new ComboBox<>();controller.rooms().forEach(r->rooms.getItems().add(r.getNumber()+" - "+r.getType()+" - $"+r.getPricePerNight()+" / noche"));rooms.getSelectionModel().selectFirst();DatePicker checkIn=new DatePicker(LocalDate.now().plusDays(1));DatePicker checkOut=new DatePicker(LocalDate.now().plusDays(3));Button book=new Button("Reservar y pagar");TextArea output=new TextArea();output.setEditable(false);book.setOnAction(e->{try{String number=rooms.getValue().split(" - ")[0];Reservation r=controller.createDemoReservation(number,checkIn.getValue(),checkOut.getValue());output.appendText("Reserva confirmada: "+r.getId()+"\nHabitación: "+r.getRoom().getNumber()+"\nTotal: $"+r.getTotal()+" COP\nEstado: "+r.getStatus()+"\nSaldo restante: $"+controller.wallet().getBalance()+"\n\n");}catch(Exception ex){new Alert(Alert.AlertType.ERROR,ex.getMessage()).showAndWait();}});Button list=new Button("Consultar reservas");list.setOnAction(e->controller.reservations().forEach(r->output.appendText(r.getId()+" | "+r.getCustomer().getName()+" | "+r.getStatus()+"\n")));VBox root=new VBox(12,title,new Label("Habitación"),rooms,new Label("Fecha de entrada"),checkIn,new Label("Fecha de salida"),checkOut,new HBox(10,book,list),new Label("Actividad del sistema"),output);root.setPadding(new Insets(20));stage.setTitle("HotelUQ - Programación II");stage.setScene(new Scene(root,720,600));stage.show();}}
